import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-07-22/nav2_odom_01_end_to_end.png",d="/Nav2ArticlesSite/article-assets/2026-07-22/nav2_odom_02_ingress_threshold.png",c="/Nav2ArticlesSite/article-assets/2026-07-22/nav2_odom_03_control_cycle.png",i="/Nav2ArticlesSite/article-assets/2026-07-22/nav2_odom_04_plugin_usage.png",n="/Nav2ArticlesSite/article-assets/2026-07-22/nav2_odom_05_smoother_feedback.png",s="/Nav2ArticlesSite/article-assets/2026-07-22/nav2_odom_06_diagnostics.png",P=JSON.parse('{"title":"机器人明明在动，Nav2 为什么还要追问速度？拆解 Odometry 如何驱动控制闭环","description":"路径告诉机器人去哪里，Costmap 告诉它哪里不能走，但真正决定“下一帧速度能改多快”的，是机器人此刻到底跑多快。这个当前速度主要来自 /odom。","frontmatter":{"title":"机器人明明在动，Nav2 为什么还要追问速度？拆解 Odometry 如何驱动控制闭环","description":"路径告诉机器人去哪里，Costmap 告诉它哪里不能走，但真正决定“下一帧速度能改多快”的，是机器人此刻到底跑多快。这个当前速度主要来自 /odom。","date":"2026-07-22","topic":"Nav2 工程实践","section":"三 · 局部控制与速度生成","readingTime":6,"source":"2026-07-22/nav2_controller_odometry_velocity_flow.md","status":"published","cover":"/article-assets/2026-07-22/nav2_odom_01_end_to_end.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-controller-odometry-velocity-flow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"机器人明明在动，Nav2 为什么还要追问速度？拆解 Odometry 如何驱动控制闭环"}],["meta",{"property":"og:description","content":"路径告诉机器人去哪里，Costmap 告诉它哪里不能走，但真正决定“下一帧速度能改多快”的，是机器人此刻到底跑多快。这个当前速度主要来自 /odom。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-controller-odometry-velocity-flow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-22/nav2_odom_01_end_to_end.png"}],["meta",{"property":"article:published_time","content":"2026-07-22"}],["meta",{"name":"twitter:title","content":"机器人明明在动，Nav2 为什么还要追问速度？拆解 Odometry 如何驱动控制闭环"}],["meta",{"name":"twitter:description","content":"路径告诉机器人去哪里，Costmap 告诉它哪里不能走，但真正决定“下一帧速度能改多快”的，是机器人此刻到底跑多快。这个当前速度主要来自 /odom。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-22/nav2_odom_01_end_to_end.png"}]],"prev":{"text":"别让机器人一上来就“甩尾”：拆解 Nav2 Rotation Shim 的全调用、状态与数据流","link":"/nav2/nav2-rotation-shim-controller-full-dataflow"},"next":{"text":"每 50 毫秒淘汰数百种走法：DWB 如何从速度窗口里选出机器人下一步？","link":"/nav2/nav2-dwb-core-algorithm"}},"headers":[],"relativePath":"nav2/nav2-controller-odometry-velocity-flow.md","filePath":"nav2/nav2-controller-odometry-velocity-flow.md","lastUpdated":null}'),h={name:"nav2/nav2-controller-odometry-velocity-flow.md"};function m(p,e,_,u,v,y){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="机器人明明在动-nav2-为什么还要追问速度-拆解-odometry-如何驱动控制闭环" tabindex="-1">机器人明明在动，Nav2 为什么还要追问速度？拆解 Odometry 如何驱动控制闭环 <a class="header-anchor" href="#机器人明明在动-nav2-为什么还要追问速度-拆解-odometry-如何驱动控制闭环" aria-label="Permalink to &quot;机器人明明在动，Nav2 为什么还要追问速度？拆解 Odometry 如何驱动控制闭环&quot;">​</a></h1><p>路径告诉机器人去哪里，Costmap 告诉它哪里不能走，但真正决定“下一帧速度能改多快”的，是机器人此刻到底跑多快。这个当前速度主要来自 <code>/odom</code>。</p><p>本文沿当前仓库源码拆开 Controller Server、五类控制器与 Velocity Smoother，讲清 Odometry 的速度从哪里进入、在哪里被使用，以及为什么命令速度不等于实测速度。</p><h2 id="一、控制模块的输入输出边界" tabindex="-1">一、控制模块的输入输出边界 <a class="header-anchor" href="#一、控制模块的输入输出边界" aria-label="Permalink to &quot;一、控制模块的输入输出边界&quot;">​</a></h2><h3 id="_1-1-followpath-只是任务入口" tabindex="-1">1.1 FollowPath 只是任务入口 <a class="header-anchor" href="#_1-1-followpath-只是任务入口" aria-label="Permalink to &quot;1.1 FollowPath 只是任务入口&quot;">​</a></h3><p>Controller Server 暴露 <code>FollowPath</code> Action。Goal 带来 Path、<code>controller_id</code>、<code>goal_checker_id</code> 和 <code>progress_checker_id</code>。真正计算速度时，还要汇合四类运行时输入：</p><ul><li>Local Costmap 与 footprint 碰撞代价。</li><li>TF 提供的机器人当前 Pose。</li><li><code>/odom</code> 提供的当前 <code>vx</code>、<code>vy</code>、<code>wz</code>。</li><li><code>speed_limit</code> 提供的绝对或百分比限速。</li></ul><p>Controller 插件返回 <code>TwistStamped</code>，Controller Server 再发布 <code>cmd_vel</code>。当前 Nav2 Launch 将它重映射为 <code>cmd_vel_nav</code>，交给 Velocity Smoother，平滑后再发布最终 <code>cmd_vel</code>。</p><p><img src="'+l+'" alt="Nav2 控制模块端到端数据流"></p><h2 id="二、odometry-速度怎样进入-controller-server" tabindex="-1">二、Odometry 速度怎样进入 Controller Server <a class="header-anchor" href="#二、odometry-速度怎样进入-controller-server" aria-label="Permalink to &quot;二、Odometry 速度怎样进入 Controller Server&quot;">​</a></h2><h3 id="_2-1-odomsubscriber-只保存最新速度" tabindex="-1">2.1 OdomSubscriber 只保存最新速度 <a class="header-anchor" href="#_2-1-odomsubscriber-只保存最新速度" aria-label="Permalink to &quot;2.1 OdomSubscriber 只保存最新速度&quot;">​</a></h3><p>当前源码创建 <code>nav_2d_utils::OdomSubscriber</code>，订阅 Controller Server 的 <code>odom_topic</code>。回调从 <code>nav_msgs/Odometry.twist.twist</code> 中提取 <code>linear.x</code>、<code>linear.y</code> 和 <code>angular.z</code>，写入互斥保护的 <code>Twist2DStamped</code> 缓存。</p><p>这里没有滑动平均，也没有使用 Pose 和 covariance。控制位姿来自 Local Costmap 的 TF 查询，不是 Odometry 消息里的 Pose。</p><h3 id="_2-2-小速度先被归零" tabindex="-1">2.2 小速度先被归零 <a class="header-anchor" href="#_2-2-小速度先被归零" aria-label="Permalink to &quot;2.2 小速度先被归零&quot;">​</a></h3><p>每个控制周期读取最新 Twist 后，<code>getThresholdedTwist()</code> 会应用 <code>min_x_velocity_threshold</code>、<code>min_y_velocity_threshold</code> 和 <code>min_theta_velocity_threshold</code>。绝对值不超过阈值的分量直接变成零。</p><p>阈值能压掉静止噪声，但过大也会让低速爬行被控制器误认为静止。当前实车配置为 <code>0.001 m/s</code>、<code>0.5 m/s</code> 和 <code>0.001 rad/s</code>；差速底盘不使用横移，因此 <code>vy</code> 的大阈值不会影响正常运动。</p><p><img src="'+d+'" alt="Odometry 字段提取、缓存与阈值化"></p><h2 id="三、20-hz-控制周期怎样汇合数据" tabindex="-1">三、20 Hz 控制周期怎样汇合数据 <a class="header-anchor" href="#三、20-hz-控制周期怎样汇合数据" aria-label="Permalink to &quot;三、20 Hz 控制周期怎样汇合数据&quot;">​</a></h2><h3 id="_3-1-pose、进展和速度依次就位" tabindex="-1">3.1 Pose、进展和速度依次就位 <a class="header-anchor" href="#_3-1-pose、进展和速度依次就位" aria-label="Permalink to &quot;3.1 Pose、进展和速度依次就位&quot;">​</a></h3><p>当前 <code>controller_frequency</code> 为 <code>20 Hz</code>。每轮先从 Costmap／TF 取得 Pose，再由 ProgressChecker 判断机器人是否持续取得位移进展，随后读取并阈值化 Odometry Twist。</p><p>Controller Server 调用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">computeVelocityCommands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(pose, current_twist, goal_checker)</span></span></code></pre></div><p>插件内部再读取已缓存的 Path、Costmap 和 TF，输出本周期建议速度。异常在 <code>failure_tolerance</code> 内会暂时转换为零速度，持续超时才让 FollowPath 失败。</p><h3 id="_3-2-命令反馈不是实测反馈" tabindex="-1">3.2 命令反馈不是实测反馈 <a class="header-anchor" href="#_3-2-命令反馈不是实测反馈" aria-label="Permalink to &quot;3.2 命令反馈不是实测反馈&quot;">​</a></h3><p>FollowPath Feedback 中的 <code>speed</code> 来自本周期 <code>cmd_vel</code> 的线速度模长，<code>distance_to_goal</code> 来自当前 Pose 到剩余 Path 的长度。它们用于任务反馈，但 <code>speed</code> 不是 <code>/odom</code> 实测速度。</p><p><img src="'+c+'" alt="Controller Server 单周期数据汇合"></p><h2 id="四、五类控制器如何使用当前速度" tabindex="-1">四、五类控制器如何使用当前速度 <a class="header-anchor" href="#四、五类控制器如何使用当前速度" aria-label="Permalink to &quot;四、五类控制器如何使用当前速度&quot;">​</a></h2><h3 id="_4-1-dwb-把速度当作动态窗口起点" tabindex="-1">4.1 DWB 把速度当作动态窗口起点 <a class="header-anchor" href="#_4-1-dwb-把速度当作动态窗口起点" aria-label="Permalink to &quot;4.1 DWB 把速度当作动态窗口起点&quot;">​</a></h3><p>DWB 用当前 Twist 计算加减速度约束下的可达速度窗口，并把它作为候选轨迹积分的初始速度。Odom 延迟会让动态窗口落后，表现为起步、刹车或转向预测不准。</p><h3 id="_4-2-mppi-把速度写入预测状态" tabindex="-1">4.2 MPPI 把速度写入预测状态 <a class="header-anchor" href="#_4-2-mppi-把速度写入预测状态" aria-label="Permalink to &quot;4.2 MPPI 把速度写入预测状态&quot;">​</a></h3><p>MPPI 将 <code>vx</code>、<code>vy</code>、<code>wz</code> 写入批量状态张量的首列，再从这个初始状态向未来 rollout。错误的速度符号会直接污染全部候选轨迹的起点。</p><h3 id="_4-3-rpp-用于前视和旋转约束" tabindex="-1">4.3 RPP 用于前视和旋转约束 <a class="header-anchor" href="#_4-3-rpp-用于前视和旋转约束" aria-label="Permalink to &quot;4.3 RPP 用于前视和旋转约束&quot;">​</a></h3><p>启用速度缩放前视后，RPP 用 <code>|vx| × lookahead_time</code> 计算前视距离；原地转向时，又以当前 <code>wz</code> 和 <code>max_angular_accel × dt</code> 限制下一帧角速度。</p><h3 id="_4-4-rotation-shim-可选择闭环角速度" tabindex="-1">4.4 Rotation Shim 可选择闭环角速度 <a class="header-anchor" href="#_4-4-rotation-shim-可选择闭环角速度" aria-label="Permalink to &quot;4.4 Rotation Shim 可选择闭环角速度&quot;">​</a></h3><p><code>closed_loop=true</code> 时，Rotation Shim 使用 Odometry 的 <code>wz</code> 作为旋转加速度窗口起点；关闭后使用上一帧命令角速度。当前实车配置开启了该闭环。</p><h3 id="_4-5-graceful-当前忽略速度参数" tabindex="-1">4.5 Graceful 当前忽略速度参数 <a class="header-anchor" href="#_4-5-graceful-当前忽略速度参数" aria-label="Permalink to &quot;4.5 Graceful 当前忽略速度参数&quot;">​</a></h3><p>Controller 接口统一传入 Twist，不代表每个插件都使用它。当前 Graceful Controller 的实现显式忽略 <code>velocity</code> 参数。</p><p><img src="'+i+'" alt="Odometry 速度在五类 Controller 中的用途"></p><h2 id="五、odometry-还会影响到达判定吗" tabindex="-1">五、Odometry 还会影响到达判定吗 <a class="header-anchor" href="#五、odometry-还会影响到达判定吗" aria-label="Permalink to &quot;五、Odometry 还会影响到达判定吗&quot;">​</a></h2><h3 id="_5-1-取决于-goalchecker-类型" tabindex="-1">5.1 取决于 GoalChecker 类型 <a class="header-anchor" href="#_5-1-取决于-goalchecker-类型" aria-label="Permalink to &quot;5.1 取决于 GoalChecker 类型&quot;">​</a></h3><p>Controller Server 会再次读取阈值化 Odom Twist，并与当前 Pose、目标 Pose 一起传入 GoalChecker。</p><p><code>SimpleGoalChecker</code> 和 <code>PositionGoalChecker</code> 只判断位置与朝向，不使用速度。<code>StoppedGoalChecker</code> 才会额外检查平移和旋转速度是否低于停止阈值。因此“进入目标容差”和“机器人已经停稳”不是同一个条件。</p><h2 id="六、velocity-smoother-的两种反馈模式" tabindex="-1">六、Velocity Smoother 的两种反馈模式 <a class="header-anchor" href="#六、velocity-smoother-的两种反馈模式" aria-label="Permalink to &quot;六、Velocity Smoother 的两种反馈模式&quot;">​</a></h2><h3 id="_6-1-open-loop-使用上一帧输出" tabindex="-1">6.1 OPEN_LOOP 使用上一帧输出 <a class="header-anchor" href="#_6-1-open-loop-使用上一帧输出" aria-label="Permalink to &quot;6.1 OPEN_LOOP 使用上一帧输出&quot;">​</a></h3><p><code>OPEN_LOOP</code> 下，平滑器把自己的 <code>last_cmd</code> 当作当前速度，再执行绝对速度 clamp、加减速度限制、死区和超时减速。此时 <code>/odom</code> 仍进入 Controller Server，但不进入 Velocity Smoother。</p><h3 id="_6-2-closed-loop-使用平均-odometry" tabindex="-1">6.2 CLOSED_LOOP 使用平均 Odometry <a class="header-anchor" href="#_6-2-closed-loop-使用平均-odometry" aria-label="Permalink to &quot;6.2 CLOSED_LOOP 使用平均 Odometry&quot;">​</a></h3><p><code>CLOSED_LOOP</code> 下，平滑器独立创建 <code>nav2_util::OdomSmoother</code>。它保留 <code>odom_duration</code> 时间窗内的 Odometry，并对各 Twist 分量做算术平均，以这个实测均值作为加减速度约束的起点。</p><p>闭环更贴近真实底盘，但要求 Odometry 高频、低延迟。平滑频率高于 Odom 更新频率，或窗口过长时，反馈会滞后，机器人可能加速慢、振荡或过冲。</p><p><img src="'+n+`" alt="Velocity Smoother 开环与闭环反馈"></p><h2 id="七、当前项目真正采用哪条链" tabindex="-1">七、当前项目真正采用哪条链 <a class="header-anchor" href="#七、当前项目真正采用哪条链" aria-label="Permalink to &quot;七、当前项目真正采用哪条链&quot;">​</a></h2><h3 id="_7-1-controller-是速度闭环-末端平滑仍是开环" tabindex="-1">7.1 Controller 是速度闭环，末端平滑仍是开环 <a class="header-anchor" href="#_7-1-controller-是速度闭环-末端平滑仍是开环" aria-label="Permalink to &quot;7.1 Controller 是速度闭环，末端平滑仍是开环&quot;">​</a></h3><p><code>myagv_test_bringup</code> 与 <code>nav2_regulated_modules</code> 都把 <code>velocity_smoother.feedback</code> 配置为 <code>OPEN_LOOP</code>。因此当前链路是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/odom → Controller Server → Controller 插件</span></span>
<span class="line"><span>cmd_vel_nav → Velocity Smoother(last_cmd) → cmd_vel → 底盘</span></span></code></pre></div><p>若将平滑器改为 <code>CLOSED_LOOP</code>，同一 <code>/odom</code> 会被两个节点分别订阅：Controller Server 使用最新一帧，Velocity Smoother 使用时间窗均值。两者参数和延迟必须分别检查。</p><h2 id="八、实车排障抓住三层" tabindex="-1">八、实车排障抓住三层 <a class="header-anchor" href="#八、实车排障抓住三层" aria-label="Permalink to &quot;八、实车排障抓住三层&quot;">​</a></h2><h3 id="_8-1-源头层" tabindex="-1">8.1 源头层 <a class="header-anchor" href="#_8-1-源头层" aria-label="Permalink to &quot;8.1 源头层&quot;">​</a></h3><p>检查 <code>/odom</code> 频率、时间戳、<code>vx／vy／wz</code> 符号、静止噪声和响应延迟。TF 正常不代表 Twist 正确。</p><h3 id="_8-2-参数层" tabindex="-1">8.2 参数层 <a class="header-anchor" href="#_8-2-参数层" aria-label="Permalink to &quot;8.2 参数层&quot;">​</a></h3><p>核对两个节点各自的 <code>odom_topic</code>，再检查 Controller 阈值、平滑器 <code>feedback</code>、<code>odom_duration</code> 和 <code>smoothing_frequency</code>。当前本地 Controller 源码使用最新 Odom，不读取官方新版本文档中的 Controller <code>odom_duration</code>，不能跨版本照抄参数。</p><h3 id="_8-3-现象层" tabindex="-1">8.3 现象层 <a class="header-anchor" href="#_8-3-现象层" aria-label="Permalink to &quot;8.3 现象层&quot;">​</a></h3><ul><li>起步慢或转向迟钝：检查阈值、Odom 延迟和闭环窗口。</li><li>旋转抖动或过冲：检查 <code>wz</code> 噪声、符号和频率。</li><li>Nav2 命令正常但底盘异常：继续沿 Velocity Smoother、底盘适配和执行器反馈排查。</li></ul><p><img src="`+s+'" alt="Odometry 控制链排障路径"></p><h2 id="九、一句话看懂这条闭环" tabindex="-1">九、一句话看懂这条闭环 <a class="header-anchor" href="#九、一句话看懂这条闭环" aria-label="Permalink to &quot;九、一句话看懂这条闭环&quot;">​</a></h2><h3 id="_9-1-odometry-不是附属显示数据" tabindex="-1">9.1 Odometry 不是附属显示数据 <a class="header-anchor" href="#_9-1-odometry-不是附属显示数据" aria-label="Permalink to &quot;9.1 Odometry 不是附属显示数据&quot;">​</a></h3><p>Path 决定方向，Costmap 决定安全边界，Odometry 速度决定控制器从什么运动状态继续计算。它既能改变 DWB／MPPI 的未来预测，也能改变 RPP／Rotation Shim 的即时约束；在 Velocity Smoother 闭环模式下，还会再次决定最终速度每周期允许变化多少。</p><h3 id="_9-2-官方参考" tabindex="-1">9.2 官方参考 <a class="header-anchor" href="#_9-2-官方参考" aria-label="Permalink to &quot;9.2 官方参考&quot;">​</a></h3><p><a href="https://docs.nav2.org/configuration/packages/configuring-controller-server.html" target="_blank" rel="noreferrer">Nav2 Controller Server 配置</a></p><p><a href="https://docs.nav2.org/configuration/packages/configuring-velocity-smoother.html" target="_blank" rel="noreferrer">Nav2 Velocity Smoother 配置</a></p>',68)])])}const g=o(h,[["render",m]]);export{P as __pageData,g as default};
